export interface LedgerResidueTarget {
  readonly pipelineDir: string;
  readonly runId: string;
  readonly stage: string;
}

export const appendLedgerResidue = (
  target: LedgerResidueTarget,
  entries: readonly ResidueEntry[],
  now: () => string
): void => {
  if (entries.length === 0) return;
  const file = path.join(target.pipelineDir, LEDGER_FILE);
  mkdirSync(path.dirname(file), { recursive: true });
  const stamp = { runId: target.runId, stage: target.stage };
  const rows = entries
    .map(entry => `${JSON.stringify({ at: now(), round: PRE_LOOP_ROUND, kind: 'residue', ...stamp, entry })}\n`)
    .join('');
  appendFileSync(file, rows, 'utf8');
};

/** What one ranked seed query came to, and the run, stage and artifact it served. */
export interface SeedRankingRecord {
  readonly runId: string;
  readonly stage: string;
  readonly ranking: SeedRanking | undefined;
  readonly artifact: Artifact;
}

/**
 * The seed cap, observable. Written where the ranking is in scope, into the same ledger as the
 * bundle's residue: ALWAYS one `seed-ranking` row per call that ranked, so the trace needs no
 * warning to exist, and - only when the cap cut - the `bundle-over-cap` residue that warns. A
 * call that ranked nothing has nothing to trace and writes nothing.
 */
export const appendSeedRanking = (pipelineDir: string, record: SeedRankingRecord, now: () => string): void => {
  if (record.ranking === undefined) return;
  const file = path.join(pipelineDir, LEDGER_FILE);
  mkdirSync(path.dirname(file), { recursive: true });
  const stamp = { runId: record.runId, stage: record.stage };
  const row = { at: now(), round: PRE_LOOP_ROUND, kind: 'seed-ranking', ...stamp, ranking: record.ranking };
  appendFileSync(file, `${JSON.stringify(row)}\n`, 'utf8');
  const target = { pipelineDir, runId: record.runId, stage: record.stage };
  appendLedgerResidue(target, seedCapResidue(record.ranking, record.artifact), now);
};

const residueOfLine = (line: string): readonly ResidueEntry[] => {
  const parsed = parseLedgerLine(line);
  return parsed.ok && parsed.row.kind === 'residue' ? [parsed.row.entry] : [];
};

/**
 * The one ledger read every reader below shares: locate, tolerate absence, split. A missing
 * ledger is not an error here - a step whose loop never appended one has nothing to report -
 * so it yields no lines and each reader falls back to its own empty value.
 */
const ledgerLines = (ports: LoopPortsDeps, isFile: (filePath: string) => boolean): readonly string[] => {
  const file = path.join(ports.ctx.pipelineDir, LEDGER_FILE);
  return isFile(file) ? ports.read(file).split('\n') : [];
};

/** The residue a round emitted before the loop threw: the append-only ledger is its only record. */
export const recordedResidue = (ports: LoopPortsDeps, isFile: (filePath: string) => boolean): readonly ResidueEntry[] =>
  ledgerLines(ports, isFile).flatMap(residueOfLine);

type ResidueLedgerRow = Extract<LedgerRow, { readonly kind: 'residue' }>;

/** Whose bundle residue a loop reads back: its own run's, for the stages it minted. */
interface ResidueReader {
  readonly runId: string;
